insert into programs (code, name, family, summary, definition) values (
  'BAD', 'Build A Dream', 'charity-team-build', 'Teams build bicycles, children are revealed as the recipients, teams present and fit the bikes, then a facilitated debrief.',
  '{"code":"BAD","name":"Build A Dream","family":"charity-team-build","summary":"Teams build bicycles, children are revealed as the recipients, teams present and fit the bikes, then a facilitated debrief.","source":"Modeled from Ledgebrook 2026-09-16 run of show and DeVry Building a Dream 2011-12-09 agenda.","parameters":[{"key":"participants","label":"Participants","type":"int","required":true},{"key":"teams","label":"Teams / build tables","type":"int","required":true},{"key":"beneficiaries","label":"Children receiving bicycles","type":"int","required":true},{"key":"beneficiary_org","label":"Beneficiary organization","type":"text","required":true},{"key":"beneficiary_minors","label":"Beneficiaries are minors","type":"bool","default":true},{"key":"beneficiary_travels","label":"Beneficiaries travel to venue","type":"bool","default":true},{"key":"travel_distance_mi","label":"Distance, beneficiary site to venue (mi)","type":"number","required":false},{"key":"bikes_go_home_same_day","label":"Children take bicycles home from the venue","type":"bool","default":false},{"key":"event_start","label":"Participant arrival time","type":"time","required":true},{"key":"session_minutes","label":"Session length (minutes)","type":"int","help":"Typically 90 to 180 minutes; 120 is very typical. Leave blank to run at the program''s natural length of 135 minutes. Fixed steps such as the reveal keep their length; the content block, the build and the debrief absorb the difference."},{"key":"beneficiary_depart_by","label":"Hard deadline: children must depart by","type":"time","required":false},{"key":"client_descriptor","label":"How to describe the client to the beneficiary org","type":"text","default":"A company"},{"key":"beneficiary_contact_name","label":"Beneficiary org contact, first name","type":"text"},{"key":"beneficiary_transport_by","label":"Who provides beneficiary transport","type":"text","default":"the beneficiary organization"},{"key":"age_min","label":"Youngest child age","type":"int","default":8},{"key":"age_max","label":"Oldest child age","type":"int","default":12},{"key":"wheel_size_in","label":"Bicycle wheel size (inches)","type":"int","default":20},{"key":"greeter_name","label":"Who meets the children in the lobby","type":"text"},{"key":"venue_phone","label":"Venue phone","type":"text"},{"key":"holding_room","label":"Holding room","type":"text","default":"to be confirmed"},{"key":"time_with_children_min","label":"Minutes children spend with the teams","type":"int","default":25},{"key":"bike_delivery_eta","label":"Bicycles arrive at the beneficiary site by","type":"time","default":"18:00"},{"key":"want_paragraphs","label":"Ask the children for paragraphs","type":"bool","default":true},{"key":"want_drawings","label":"Ask the children for drawings","type":"bool","default":true},{"key":"sender_name","label":"Letter signed by","type":"text","default":"James Carter"},{"key":"sender_title","label":"Signer title","type":"text","default":"Founder and CEO, Be Legendary"},{"key":"sender_phone","label":"Signer phone","type":"text","default":"775-980-5703"},{"key":"sender_email","label":"Signer email","type":"text","default":"jcarter@repario.com"}],"derived":{"bikes":"beneficiaries + 2"},"quantities":[{"item":"Bicycles","formula":"beneficiaries + 2","basis":"one per child plus two spares","confidence":"high","note":"DeVry: 108 children, 110 bikes."},{"item":"Helmets","formula":"beneficiaries","basis":"one per child","confidence":"high"},{"item":"Locks","formula":"beneficiaries","basis":"one per child","confidence":"high"},{"item":"Backpacks","formula":"beneficiaries","basis":"one per child","confidence":"high"},{"item":"Build tables","formula":"teams","basis":"one per team","confidence":"high","note":"Ledgebrook: 13 teams, 13 build tables."},{"item":"Tool sets","formula":"teams","basis":"one per build table","confidence":"high","note":"Ledgebrook: one tool set per table."},{"item":"Floor pumps","formula":"max(2, ceil(teams / 6))","basis":"facilitator station","confidence":"low","note":"Ledgebrook says pumps at the facilitator station without a count. Confirm."},{"item":"Team number stickers","formula":"teams","basis":"one per team","confidence":"high"},{"item":"Client brief sheets","formula":"participants","basis":"one per participant","confidence":"medium","note":"DeVry shipped 110 brief sheets. Confirm whether this is per participant or per team."},{"item":"Holding-room activity kits","formula":"beneficiaries","basis":"one per child","confidence":"medium","note":"DeVry used coloring DVDs; Ledgebrook used activities, snacks and drinks."},{"item":"On-site technicians","formula":"max(1, ceil(bikes / 30))","basis":"inspection and correction throughput","confidence":"low","note":"DeVry: 4 mechanics for 110 bikes. Ledgebrook: 1 technician for 13. Confirm the ratio."}],"resources":[{"key":"venue","label":"Venue","always":true,"fields":["name","address","contact_name","contact_title","contact_phone","room","av_notes"]},{"key":"beneficiary_site","label":"Beneficiary organization","always":true,"fields":["org_name","address","contact_name","contact_phone","contact_email","chaperone_count","consent_status"]},{"key":"transportation","label":"Beneficiary transportation","condition":"beneficiary_travels","vehicle_rule":[{"when":"beneficiaries <= 8","vehicle":"Limousine or SUV","count_formula":"1"},{"when":"beneficiaries <= 20","vehicle":"Limousine or passenger van","count_formula":"ceil(beneficiaries / 14)"},{"when":"beneficiaries > 20","vehicle":"School or charter bus","count_formula":"ceil(beneficiaries / 40)"}],"fields":["vendor","vendor_phone","confirmation_number","vehicle_type","vehicle_count","pickup_time","distance_mi","cost"],"note":"Ledgebrook used a limousine for 13 children and it was left off the run of show entirely. DeVry used 3 buses plus a U-Haul van for materials."},{"key":"materials_transport","label":"Materials vehicle","condition":"beneficiaries > 20","fields":["vendor","confirmation_number","cost"],"note":"DeVry booked a U-Haul van for materials in addition to beneficiary buses."},{"key":"technicians","label":"On-site technicians","always":true,"count_formula":"max(1, ceil((beneficiaries + 2) / 30))","fields":["names","arrival_time","location","contact","day_rate","cost"]},{"key":"post_event_delivery","label":"Bicycle delivery to beneficiary site","condition":"not bikes_go_home_same_day","fields":["vendor","depart_time","arrive_time","destination","cost"],"note":"Ledgebrook: bicycles inspected at the venue, then delivered to the club by approximately 7:00 PM for parent pickup."},{"key":"photography","label":"Photography","always":true,"fields":["photographer","contact","cost"],"note":"Both documents call for roaming photography and a group photograph."}],"run_of_show":{"anchor":"reveal","anchor_rule":"If beneficiary_depart_by is set, reveal = beneficiary_depart_by minus 30 minutes. Otherwise reveal = event_start plus the sum of the pre-reveal main-track durations.","main_track":[{"id":"setup","label":"Setup","duration":75,"before_start":true,"details":["Bicycles staged","Build tables with one tool set each","Pumps at the facilitator station","Theater seating for the open and close","Audio and video check"]},{"id":"arrival","label":"Participants arrive and are seated","duration":15,"fixed":true,"details":["Teams pre-assigned and mixed across departments, not self-selected"]},{"id":"opening","label":"Opening remarks: client executive","duration":5,"fixed":true,"details":["Why the build closes the event","Hands off to James Carter"]},{"id":"content","label":"Be Legendary content block","duration":25,"min":12,"details":["Awareness: Moonwalking Bear","Beliefs: Shreddies","Who Are You, three rounds"]},{"id":"build","label":"Build the bicycles","duration":30,"min":18,"details":["Build instructions and client brief sheet issued","No mention of the children"]},{"id":"reveal","label":"The Reveal","duration":5,"fixed":true,"is_anchor":true,"details":["Quality inspection framing, then the children enter"]},{"id":"present","label":"Teams present the bikes, adjust fit, ride with the children","duration":15,"min":8,"details":["Roaming photography throughout"]},{"id":"photo","label":"Group photograph","duration":5,"fixed":true,"details":["This is the photograph the event is remembered by"]},{"id":"tunnel","label":"Human tunnel","duration":3,"fixed":true,"details":["Participants form the tunnel, children run out through it"]},{"id":"reset","label":"Room reset for the debrief","duration":4,"fixed":true,"details":["Build tables cleared, seating pulled in"]},{"id":"debrief","label":"Debrief, facilitated by James Carter","duration":20,"min":5,"details":["Open with: who has the first bike story?","What happened, so what, now what"]},{"id":"challenge","label":"30-Day Challenge","duration":4,"fixed":true,"details":["Voluntary, SMS based, no app","Custom client page and QR code on screen"]},{"id":"close","label":"Close: client executive","duration":4,"fixed":true,"details":["Connects the session to the client''s definition of leadership"]},{"id":"inspection","label":"Technician inspection","duration":60,"after_close":true,"details":["Every bicycle inspected and corrected at the venue"]}],"beneficiary_track":[{"id":"confirm","label":"Beneficiary org confirms departure, chaperones and consent","offset_from_reveal":-1440},{"id":"depart_origin","label":"Children depart the beneficiary site","offset_from_reveal":-75},{"id":"arrive_venue","label":"Children arrive and go directly to the holding room, out of sight of the main room","offset_from_reveal":-45},{"id":"holding","label":"Chaperones and support staff run activities, snacks and drinks","offset_from_reveal":-45,"duration":30},{"id":"sizing","label":"Sizing and helmet fitting","offset_from_reveal":-15},{"id":"send_rep","label":"One participant from each team is sent to the holding room to meet their child","offset_from_reveal":-15},{"id":"match","label":"Participants matched with children; children briefed and lined up outside the room","offset_from_reveal":-10,"duration":10},{"id":"enter","label":"Children enter with their team representative","offset_from_reveal":0},{"id":"gear","label":"Helmets, locks and backpacks presented with the bicycles","offset_from_reveal":10},{"id":"return","label":"Children returned to their chaperones","offset_from_reveal":28},{"id":"depart_venue","label":"Children depart the venue","offset_from_reveal":30}],"reveal_to_departure":30},"tasks":[{"phase":"1. Lock","title":"Signed agreement / SOW returned","offset":-30,"role":"JC"},{"phase":"1. Lock","title":"Deposit invoice sent","offset":-30,"role":"JC"},{"phase":"1. Lock","title":"W-9, COI + vendor onboarding submitted","offset":-25,"role":"JC"},{"phase":"1. Lock","title":"Deposit received","offset":-21,"role":"JC"},{"phase":"1. Lock","title":"Travel booked for facilitation team","offset":-21,"role":"JC"},{"phase":"2. Design","title":"Sponsor alignment call held (objectives + success measures)","offset":-21,"role":"JC"},{"phase":"2. Design","title":"Confirm participant count, team count and room layout","offset":-21,"role":"JC"},{"phase":"2. Design","title":"Beneficiary organization identified and agreed","offset":-21,"role":"JC"},{"phase":"2. Design","title":"Beneficiary count confirmed with the organization","offset":-18,"role":"coordinator"},{"phase":"2. Design","title":"Chaperone count and parental consent confirmed","offset":-14,"role":"coordinator","condition":"beneficiary_minors"},{"phase":"2. Design","title":"Child sizes collected for bicycle and helmet fit","offset":-14,"role":"coordinator"},{"phase":"2. Design","title":"Attendee list + roles received","offset":-14,"role":"JC"},{"phase":"2. Design","title":"Confirm hard departure deadline for the children","offset":-14,"role":"coordinator","note":"This single constraint fixes the reveal time and therefore every time before it."},{"phase":"3. Produce","title":"Bicycles ordered and ship date confirmed","offset":-21,"role":"logistics"},{"phase":"3. Produce","title":"Helmets, locks and backpacks ordered","offset":-21,"role":"logistics"},{"phase":"3. Produce","title":"Beneficiary transportation booked, confirmation number recorded","offset":-14,"role":"logistics","condition":"beneficiary_travels","note":"Left off the Ledgebrook run of show. The limousine existed but appeared in no document."},{"phase":"3. Produce","title":"Materials vehicle booked","offset":-14,"role":"logistics","condition":"beneficiaries > 20"},{"phase":"3. Produce","title":"On-site technicians booked and day rate agreed","offset":-14,"role":"logistics"},{"phase":"3. Produce","title":"Post-event bicycle delivery to beneficiary site arranged","offset":-14,"role":"logistics","condition":"not bikes_go_home_same_day"},{"phase":"3. Produce","title":"Photographer booked","offset":-14,"role":"logistics"},{"phase":"3. Produce","title":"Venue AV, room layout and holding room confirmed in writing","offset":-10,"role":"logistics","note":"The holding room must be out of sight of the main room or the reveal is spoiled."},{"phase":"3. Produce","title":"Brief sheets and team number stickers printed","offset":-10,"role":"logistics"},{"phase":"3. Produce","title":"Holding-room activity kits prepared","offset":-10,"role":"coordinator"},{"phase":"3. Produce","title":"Client challenge page live and QR code tested","offset":-7,"role":"JC"},{"phase":"3. Produce","title":"Materials shipped; tracking number recorded","offset":-7,"role":"logistics"},{"phase":"3. Produce","title":"Run of show approved by sponsor","offset":-7,"role":"JC"},{"phase":"3. Produce","title":"Content videos tested on the delivery device","offset":-5,"role":"JC"},{"phase":"3. Produce","title":"Coordination doc issued to all contractors","offset":-5,"role":"JC"},{"phase":"3. Produce","title":"Materials arrival confirmed at venue","offset":-2,"role":"logistics"},{"phase":"3. Produce","title":"Transportation reconfirmed with vendor","offset":-1,"role":"logistics","condition":"beneficiary_travels"},{"phase":"3. Produce","title":"Beneficiary org reconfirmed: departure time, chaperones, headcount","offset":-1,"role":"coordinator"},{"phase":"4. Deliver","title":"Delivery day","offset":0,"role":"all"},{"phase":"4. Deliver","title":"Bicycle inspection complete at venue","offset":0,"role":"technician"},{"phase":"4. Deliver","title":"Bicycles delivered to beneficiary site","offset":0,"role":"logistics","condition":"not bikes_go_home_same_day"},{"phase":"5. Close","title":"Thank-you + recap email to sponsor","offset":2,"role":"JC"},{"phase":"5. Close","title":"Thank-you to the beneficiary organization","offset":2,"role":"coordinator"},{"phase":"5. Close","title":"Photographs delivered to client","offset":3,"role":"logistics"},{"phase":"5. Close","title":"Final invoice sent","offset":3,"role":"JC"},{"phase":"5. Close","title":"Contractor invoices received and reconciled","offset":7,"role":"JC"},{"phase":"5. Close","title":"Event P&L closed","offset":10,"role":"JC"},{"phase":"5. Close","title":"Debrief call with sponsor held","offset":14,"role":"JC"},{"phase":"5. Close","title":"Final payment received","offset":30,"role":"JC"},{"phase":"2. Design","title":"Coordination letter sent to the beneficiary organization","offset":-21,"role":"coordinator","note":"Generate it from this engagement rather than editing last event''s copy. That is how a letter ends up quoting the wrong arrival time."},{"phase":"2. Design","title":"Child first names and ages received","offset":-10,"role":"coordinator","note":"Ages drive the wheel size. Without them the bicycle order is a guess."},{"phase":"2. Design","title":"Accompanying staff names received","offset":-10,"role":"coordinator"},{"phase":"2. Design","title":"Paragraphs and drawings requested","offset":-14,"role":"coordinator","condition":"want_paragraphs or want_drawings","note":"Optional for the children, but the adults building the bicycles value them most."},{"phase":"3. Produce","title":"Holding room confirmed and sent to the beneficiary organization","offset":-1,"role":"coordinator","note":"The letter goes out before the room is known, so this closes the gap."},{"phase":"3. Produce","title":"Confirm who meets the children in the lobby","offset":-2,"role":"coordinator"}],"cost_lines":[{"key":"bicycles","label":"Bicycles","visibility":"contractor"},{"key":"gear","label":"Helmets, locks, backpacks","visibility":"contractor"},{"key":"print","label":"Printed materials","visibility":"contractor"},{"key":"freight","label":"Freight and shipping","visibility":"contractor"},{"key":"transportation","label":"Beneficiary transportation","visibility":"contractor"},{"key":"technicians","label":"On-site technicians","visibility":"contractor"},{"key":"photography","label":"Photography","visibility":"contractor"},{"key":"venue_av","label":"Venue and AV charges","visibility":"contractor"},{"key":"travel","label":"Facilitation team travel","visibility":"contractor"},{"key":"contractor_fees","label":"Contractor fees","visibility":"contractor"},{"key":"client_fee","label":"Client fee","visibility":"owner"},{"key":"margin","label":"Gross margin","visibility":"owner","computed":"client_fee - sum(all contractor-visible lines)"}],"documents":[{"key":"beneficiary-letter","title":"{{beneficiary_org}} coordination letter","audience":"The beneficiary organization","purpose":"Sent about three weeks out. Tells the club or school when to arrive, how many children to select, what to bring, and who holds custody.","send_offset":-21,"greeting":"Hello {{beneficiary_contact_name}},","sections":[{"body":["It was a pleasure speaking with you about our {{name}} event. We are very excited to have the {{beneficiary_org}} involved in this event.","Here are some details for you..."]},{"heading":"WHEN","body":["{{delivery_date}}","Children arrive on site at {{arrive_venue_time}} to approximately {{depart_venue_time}}"]},{"heading":"WHERE","body":["{{venue_name}}","{{venue_address}}","{{venue_phone}}","The room is {{holding_room}}. I will be in touch the day before and the day of the event to be sure we are on track and to give you any additional details."]},{"heading":"WHO","body":["{{client_descriptor}} is holding a leadership event for {{participants}} leaders. The bicycle build is the closing session."]},{"heading":"BEFORE THE EVENT: OFFSITE COORDINATION","body":["We will be building {{beneficiaries}} bicycles for {{beneficiaries}} children. We ask that you select {{beneficiaries}} children, between {{age_min}} and {{age_max}} years old ({{wheel_size_in}} inch bicycles), from your club who you feel will most benefit from receiving a brand new bicycle.","We are expecting {{beneficiary_transport_by}} to provide transportation of the children to and from the location listed above.","Please send me the first name and age of each child once your list is set, along with the names of the staff who will accompany them."]},{"heading":"PARAGRAPHS","condition":"want_paragraphs","body":["These are optional. If the children have time to do them, the adults love them, and they are one of the most meaningful parts of the day for the people building the bicycles.","Here are some guidelines for the paragraphs:"],"ordered":true,"bullets":["One paragraph from each child who will be receiving the bicycle.","Please have the kids write a paragraph about what their life would be like with a bicycle. What does it mean to have a bicycle? Do they feel excited? Do they feel proud? Where will they go with their bicycle?","Have them sign the paragraph with their name.","Please bring the paragraphs with you to the event."]},{"heading":"DRAWINGS","condition":"want_drawings","body":["Also optional, and also a favorite of the adults. It can be both drawings and paragraphs or neither. Just one small part of reciprocating that helps the children accept the bike because they are giving too."],"ordered":true,"bullets":["One from each child.","Please have the kids draw a picture of them riding a bicycle.","Please only have them draw; no words.","Have them write their name on the BACK of the drawing.","Please use markers, preferably black.","Landscape orientation.","If doing them, please bring the drawings with you to the event. They are given to the adults who built the bicycles."]},{"heading":"DURING THE EVENT: ONSITE COORDINATION","body":["Please arrive at the holding room ({{holding_room}}) by {{arrive_venue_time}}. {{greeter_name}} will meet you in the lobby and walk you to the holding room. This can be a large venue and it may take some time to find each other and get to the room, so arriving fifteen minutes earlier may be better.","We will provide drinks for the children while they wait.","Each child will be paired with one adult from a team. The purpose of the pairing is to make the child as comfortable as possible. Those adults stay with the children and walk them into the room when the bicycles are revealed.","I will check in with you shortly after you arrive and will be back roughly five minutes before the reveal to guide you to the doors. The reveal is expected at approximately {{reveal}}.","Upon entering the build room, each child will go with their adult buddy to a group of adults and be presented with their bicycle. They will be with the adults for roughly {{time_with_children_min}} minutes. We will take a group photo, the children will exit through a tunnel of adults, and then we will say goodbye. The children should be on their way by approximately {{depart_venue_time}}.","Each child will also receive a helmet, lock, and backpack while in the room. These go home with the child that evening."]},{"heading":"AFTER THE EVENT: TRANSPORTATION OF BIKES","condition":"not bikes_go_home_same_day","body":["Every bicycle is inspected and corrected by a Be Legendary bicycle technician after the program, at the venue, before it leaves. We will then transport the bicycles to the {{beneficiary_org}} that evening. We expect to arrive by approximately {{bike_delivery_eta}}. Please be sure someone is there to meet us so the bicycles can be dropped off.","Please do not tell the children they can pick up their bicycles that night until our technicians have completed their inspection and the bicycles have arrived."]},{"heading":"A NOTE ON THE CHILDREN","condition":"beneficiary_minors","body":["The {{beneficiary_org}} retains legal custody and responsibility for the children throughout the event. Be Legendary staff supervise the children while they are in our care at the venue, in coordination with your staff. Please plan to have your staff with the children at all times."]},{"heading":"THANK YOU","body":["Thank you so much for being a part of this event. It really is a joy to be a part of, and I know you, your staff, and the children will be thrilled.","Please don''t hesitate to contact me with any questions or concerns."]}],"signoff":["{{sender_name}}","{{sender_title}}","{{sender_phone}}","{{sender_email}}"]}]}'::jsonb
)
on conflict (code) do update set
  name = excluded.name, family = excluded.family,
  summary = excluded.summary, definition = excluded.definition,
  updated_at = now();

insert into programs (code, name, family, summary, definition) values (
  'GOB', 'Get On Board', 'charity-team-build', 'Two hours on change. Teams assemble skateboards from a bag of parts with no instructions, a hands-on lesson in embracing change, then gift the boards to local kids.',
  '{"code":"GOB","name":"Get On Board","family":"charity-team-build","summary":"Two hours on change. Teams assemble skateboards from a bag of parts with no instructions, a hands-on lesson in embracing change, then gift the boards to local kids.","source":"Modeled from the Be Legendary Experience Information 2026 catalogue: the description, the two-hour duration and the change theme. Durations, quantities and ratios below are inferred from the proven give-back spine and are marked as such.","parameters":[{"key":"participants","label":"Participants","type":"int","required":true},{"key":"teams","label":"Teams","type":"int","required":true},{"key":"beneficiaries","label":"Children receiving boards","type":"int","required":true},{"key":"beneficiary_org","label":"Youth organization partner","type":"text","required":true},{"key":"beneficiary_contact_name","label":"Partner contact, first name","type":"text"},{"key":"age_min","label":"Youngest child age","type":"int","default":8},{"key":"age_max","label":"Oldest child age","type":"int","default":14},{"key":"beneficiary_minors","label":"Beneficiaries are minors","type":"bool","default":true},{"key":"beneficiary_travels","label":"Children travel to the venue","type":"bool","default":true},{"key":"boards_go_home_same_day","label":"Children take the boards home on the day","type":"bool","default":true},{"key":"safety_gear","label":"Helmets and pads included","type":"bool","default":true,"help":"A skateboard without a helmet is a liability conversation. Default is yes."},{"key":"event_start","label":"Participant arrival time","type":"time","required":true},{"key":"session_minutes","label":"Session length (minutes)","type":"int","help":"Typically 90 to 180 minutes; 120 is very typical. Leave blank to run at the program''s natural length of 125 minutes. Fixed steps such as the reveal keep their length; the content block, the build and the debrief absorb the difference."},{"key":"beneficiary_depart_by","label":"Hard deadline: children must depart by","type":"time"},{"key":"client_descriptor","label":"How to describe the client to the partner","type":"text","default":"A company"},{"key":"beneficiary_transport_by","label":"Who provides child transport","type":"text","default":"the partner organization"},{"key":"greeter_name","label":"Who meets the children on arrival","type":"text"},{"key":"holding_room","label":"Holding area","type":"text","default":"to be confirmed"},{"key":"venue_phone","label":"Venue phone","type":"text"},{"key":"sender_name","label":"Letter signed by","type":"text","default":"James Carter"},{"key":"sender_title","label":"Signer title","type":"text","default":"Founder and CEO, Be Legendary"},{"key":"sender_phone","label":"Signer phone","type":"text","default":"775-980-5703"},{"key":"sender_email","label":"Signer email","type":"text","default":"jcarter@repario.com"}],"derived":{"boards":"beneficiaries + 2"},"quantities":[{"item":"Skateboards (parts bags)","formula":"boards","basis":"one per child plus two spares","confidence":"medium","note":"Spares follow the bicycle build''s pattern. Confirm."},{"item":"Helmets","formula":"beneficiaries","basis":"one per child","confidence":"high"},{"item":"Pad sets","formula":"beneficiaries","basis":"one per child","confidence":"medium"},{"item":"Build tables","formula":"teams","basis":"one per team","confidence":"medium"},{"item":"Tool sets","formula":"teams","basis":"one per build table","confidence":"medium","note":"Skate tools specifically. Confirm what a parts bag assumes is on the table."},{"item":"Team number stickers","formula":"teams","basis":"one per team","confidence":"high"},{"item":"Client brief sheets","formula":"participants","basis":"one per participant","confidence":"medium"},{"item":"On-site technicians","formula":"max(1, ceil(boards / 30))","basis":"inspection before a child rides","confidence":"low","note":"Ratio copied from the bicycle build. A board assembled wrong is a safety issue, so confirm this one."}],"resources":[{"key":"venue","label":"Venue","always":true,"fields":["name","address","contact_name","contact_phone","room","floor_notes","av_notes"],"note":"Children may want to try the boards. Confirm whether riding indoors is permitted and where."},{"key":"youth_partner","label":"Youth organization partner","always":true,"fields":["org_name","address","contact_name","contact_phone","contact_email","child_count","chaperone_count","consent_status","arrival_time"]},{"key":"child_transport","label":"Child transport","condition":"beneficiary_travels","vehicle_rule":[{"when":"beneficiaries <= 8","vehicle":"Van or car pool","count_formula":"1"},{"when":"beneficiaries <= 20","vehicle":"Minibus or van","count_formula":"ceil(beneficiaries / 14)"},{"when":"beneficiaries > 20","vehicle":"School or charter bus","count_formula":"ceil(beneficiaries / 40)"}],"fields":["vendor","vendor_phone","confirmation_number","vehicle_type","vehicle_count","pickup_time","cost"]},{"key":"technicians","label":"On-site technicians","always":true,"count_formula":"max(1, ceil(boards / 30))","fields":["names","arrival_time","location","contact","day_rate","cost"],"note":"Every board is inspected before it leaves. Trucks and hardware torque are the usual faults."},{"key":"photography","label":"Photography","always":true,"fields":["photographer","contact","cost"]}],"run_of_show":{"anchor":"reveal","anchor_rule":"The children are revealed as the recipients after the build. If the engagement has a hard departure deadline, the schedule is placed backward from it; otherwise it runs forward from arrival.","reveal_to_departure":40,"main_track":[{"id":"setup","label":"Setup","duration":90,"before_start":true,"details":["Parts bags staged unopened","Build tables with one skate tool set each","Theater seating for the open and close","Audio and video check"]},{"id":"arrival","label":"Participants arrive and are seated","duration":15,"fixed":true},{"id":"opening","label":"Opening remarks: client executive","duration":5,"fixed":true},{"id":"content","label":"Be Legendary content block: change","duration":25,"min":12,"details":["The parts bag arrives with no instructions on purpose","Connection Points woven in per the sponsor''s objectives"]},{"id":"build","label":"Assemble the skateboards","duration":30,"min":18,"details":["A bag of parts, no instructions","Teams work out the sequence themselves","No mention of the children"]},{"id":"reveal","label":"The Reveal: the children enter","duration":5,"fixed":true,"is_anchor":true},{"id":"present","label":"Teams present the boards, fit helmets, ride with the children","duration":20,"min":10,"details":["Roaming photography throughout"]},{"id":"photo","label":"Group photograph","duration":5,"fixed":true},{"id":"tunnel","label":"Human tunnel","duration":3,"fixed":true},{"id":"reset","label":"Room reset for the debrief","duration":3,"fixed":true},{"id":"debrief","label":"Debrief: what changed and when you noticed","duration":10,"min":5},{"id":"close","label":"Close: client executive","duration":4,"fixed":true},{"id":"inspection","label":"Technician inspection of every board","duration":45,"after_close":true}],"beneficiary_track":[{"id":"confirm","label":"Partner confirms departure, chaperones and consent","offset_from_reveal":-1440},{"id":"depart_origin","label":"Children depart the partner organization","offset_from_reveal":-75},{"id":"arrive_venue","label":"Children arrive and go to the holding area, out of sight of the room","offset_from_reveal":-45},{"id":"holding","label":"Chaperones and support staff run the holding area","offset_from_reveal":-45,"duration":30},{"id":"sizing","label":"Helmet and pad fitting","offset_from_reveal":-15},{"id":"send_rep","label":"One participant from each team sent to meet their child","offset_from_reveal":-15},{"id":"enter","label":"Children enter with their team representative","offset_from_reveal":0},{"id":"gear","label":"Helmets and pads presented with the boards","offset_from_reveal":10},{"id":"return","label":"Children returned to their chaperones","offset_from_reveal":38},{"id":"depart_venue","label":"Children depart the venue","offset_from_reveal":40}]},"tasks":[{"phase":"1. Lock","title":"Signed agreement / SOW returned","offset":-30,"role":"JC"},{"phase":"1. Lock","title":"Deposit invoice sent","offset":-30,"role":"JC"},{"phase":"1. Lock","title":"W-9, COI + vendor onboarding submitted","offset":-25,"role":"JC"},{"phase":"1. Lock","title":"Deposit received","offset":-21,"role":"JC"},{"phase":"1. Lock","title":"Travel booked for facilitation team","offset":-21,"role":"JC"},{"phase":"2. Design","title":"Sponsor alignment call held (objectives + success measures)","offset":-25,"role":"JC"},{"phase":"2. Design","title":"Connection Points agreed with the sponsor","offset":-21,"role":"JC","note":"Customized to the client''s objectives through Connection Points woven into the build."},{"phase":"2. Design","title":"Participant count and team count confirmed","offset":-21,"role":"JC"},{"phase":"2. Design","title":"Nonprofit partner matched and agreed","offset":-25,"role":"coordinator","note":"Benefits a vetted local nonprofit matched to the experience and the client''s market."},{"phase":"2. Design","title":"Attendee list + roles received","offset":-14,"role":"JC"},{"phase":"2. Design","title":"Content outline drafted","offset":-14,"role":"JC"},{"phase":"2. Design","title":"Content outline approved by sponsor","offset":-10,"role":"JC"},{"phase":"3. Produce","title":"Skateboard parts bags ordered and ship date confirmed","offset":-21,"role":"logistics","note":"The catalogue states four to twelve weeks'' lead time is ideal. Offsets here sit at the short end; a larger room needs the long end."},{"phase":"3. Produce","title":"Run-of-show drafted","offset":-10,"role":"JC"},{"phase":"3. Produce","title":"AV + room requirements confirmed with venue","offset":-7,"role":"logistics"},{"phase":"3. Produce","title":"Run of show approved by sponsor","offset":-7,"role":"JC"},{"phase":"3. Produce","title":"Slides and media final","offset":-5,"role":"JC"},{"phase":"3. Produce","title":"Materials shipped; tracking number recorded","offset":-7,"role":"logistics"},{"phase":"3. Produce","title":"Materials arrival confirmed at venue","offset":-2,"role":"logistics"},{"phase":"3. Produce","title":"Final logistics email to sponsor","offset":-3,"role":"JC"},{"phase":"4. Deliver","title":"Delivery day","offset":0,"role":"all"},{"phase":"5. Close","title":"Thank-you + recap email to sponsor","offset":2,"role":"JC"},{"phase":"5. Close","title":"Participant feedback survey sent","offset":2,"role":"JC"},{"phase":"5. Close","title":"Photographs delivered to client","offset":3,"role":"logistics"},{"phase":"5. Close","title":"Final invoice sent","offset":3,"role":"JC"},{"phase":"5. Close","title":"Contractor invoices received and reconciled","offset":7,"role":"JC"},{"phase":"5. Close","title":"Event P&L closed","offset":10,"role":"JC"},{"phase":"5. Close","title":"Debrief call with sponsor held","offset":14,"role":"JC"},{"phase":"5. Close","title":"Final payment received","offset":30,"role":"JC"},{"phase":"2. Design","title":"Coordination letter sent to the nonprofit partner","offset":-21,"role":"coordinator"},{"phase":"2. Design","title":"Beneficiary count confirmed with the partner","offset":-18,"role":"coordinator"},{"phase":"3. Produce","title":"Beneficiary transport booked, confirmation number recorded","offset":-14,"role":"logistics","condition":"beneficiary_travels"},{"phase":"3. Produce","title":"Holding area confirmed, out of sight of the main room","offset":-7,"role":"coordinator","note":"If the beneficiaries can be seen before the reveal, the moment the room turns on is lost."},{"phase":"3. Produce","title":"Partner reconfirmed: arrival time, escorts, headcount","offset":-1,"role":"coordinator"},{"phase":"5. Close","title":"Thank-you to the nonprofit partner","offset":2,"role":"coordinator"},{"phase":"2. Design","title":"Chaperone count and parental consent confirmed","offset":-14,"role":"coordinator","condition":"beneficiary_minors"},{"phase":"2. Design","title":"Child first names and ages received","offset":-14,"role":"coordinator","note":"Ages drive board and helmet sizing."},{"phase":"3. Produce","title":"Helmets and pads ordered","offset":-21,"role":"logistics","condition":"safety_gear"},{"phase":"3. Produce","title":"On-site technicians booked and day rate agreed","offset":-14,"role":"logistics"},{"phase":"3. Produce","title":"Confirm whether riding indoors is permitted, and where","offset":-14,"role":"logistics","note":"The children will want to try them. Decide before the day, not during it."},{"phase":"4. Deliver","title":"Board inspection complete before any child rides","offset":0,"role":"technician","note":"Loose trucks and untorqued hardware are the usual faults."}],"cost_lines":[{"key":"materials","label":"Materials and donated goods","visibility":"contractor"},{"key":"safety_gear","label":"Helmets and pads","visibility":"contractor"},{"key":"child_transport","label":"Child transport","visibility":"contractor"},{"key":"technicians","label":"On-site technicians","visibility":"contractor"},{"key":"print","label":"Printed materials","visibility":"contractor"},{"key":"freight","label":"Freight and shipping","visibility":"contractor"},{"key":"venue_av","label":"Venue and AV charges","visibility":"contractor"},{"key":"facilitation","label":"Facilitation crew","visibility":"contractor"},{"key":"photography","label":"Photography","visibility":"contractor"},{"key":"travel","label":"Facilitation team travel","visibility":"contractor"},{"key":"contractor_fees","label":"Contractor fees","visibility":"contractor"},{"key":"client_fee","label":"Client fee","visibility":"owner"},{"key":"margin","label":"Gross margin","visibility":"owner","computed":"client_fee - sum(all contractor-visible lines)"}]}'::jsonb
)
