insert into programs (code, name, family, summary, definition) values (
  'HW', 'Housewarming', 'charity-team-build', 'Sixty to ninety minutes. The room builds real homes for animals waiting to be adopted. When the group hits its goal, the animals arrive.',
  '{"code":"HW","name":"Housewarming","family":"charity-team-build","summary":"Sixty to ninety minutes. The room builds real homes for animals waiting to be adopted. When the group hits its goal, the animals arrive.","source":"Modeled from the Be Legendary Experience Information 2026 catalogue, which gives the description, the 60-90 minute band and the shared turn-key terms. Durations, quantities and ratios below are inferred from the proven give-back spine and are marked as such.","parameters":[{"key":"participants","label":"Participants","type":"int","required":true},{"key":"teams","label":"Teams","type":"int","required":true,"help":"One animal home per team is the assumption. Confirm."},{"key":"beneficiaries","label":"Animals arriving","type":"int","required":true},{"key":"beneficiary_org","label":"Shelter or rescue partner","type":"text","required":true},{"key":"beneficiary_contact_name","label":"Partner contact, first name","type":"text"},{"key":"handlers","label":"Animal handlers accompanying","type":"int","default":0,"help":"The partner''s own staff. They stay with the animals throughout. Defaulted so the handler ratio still computes before the partner has told us."},{"key":"beneficiary_minors","label":"Beneficiaries are minors","type":"bool","default":false,"help":"False for animals. Kept so the shared custody language stays off the letter."},{"key":"beneficiary_travels","label":"Animals travel to the venue","type":"bool","default":true},{"key":"homes_go_to_shelter","label":"Homes delivered to the shelter afterwards","type":"bool","default":true,"help":"Animals rarely leave with their home on the day."},{"key":"floor_protection","label":"Floor protection confirmed","type":"bool","default":false,"help":"Venues almost always require it before live animals come indoors."},{"key":"event_start","label":"Participant arrival time","type":"time","required":true},{"key":"session_minutes","label":"Session length (minutes)","type":"int","help":"Typically 90 to 180 minutes; 120 is very typical. Leave blank to run at the program''s natural length of 97 minutes. Fixed steps such as the reveal keep their length; the content block, the build and the debrief absorb the difference."},{"key":"beneficiary_depart_by","label":"Hard deadline: animals must depart by","type":"time","help":"Animal welfare usually sets a firm limit. Set it and the schedule is placed backward from it."},{"key":"client_descriptor","label":"How to describe the client to the partner","type":"text","default":"A company"},{"key":"greeter_name","label":"Who meets the partner on arrival","type":"text"},{"key":"holding_room","label":"Holding area","type":"text","default":"to be confirmed"},{"key":"venue_phone","label":"Venue phone","type":"text"},{"key":"sender_name","label":"Letter signed by","type":"text","default":"James Carter"},{"key":"sender_title","label":"Signer title","type":"text","default":"Founder and CEO, Be Legendary"},{"key":"sender_phone","label":"Signer phone","type":"text","default":"775-980-5703"},{"key":"sender_email","label":"Signer email","type":"text","default":"jcarter@repario.com"}],"derived":{"homes":"teams","animals_per_handler":"beneficiaries / max(1, handlers)"},"quantities":[{"item":"Animal home kits","formula":"teams + 1","basis":"one per team plus a spare","confidence":"medium","note":"One home per team is inferred from the bicycle build. Confirm whether homes are per team or per animal."},{"item":"Build tables","formula":"teams","basis":"one per team","confidence":"medium"},{"item":"Tool sets","formula":"teams","basis":"one per build table","confidence":"medium"},{"item":"Team number stickers","formula":"teams","basis":"one per team","confidence":"high"},{"item":"Client brief sheets","formula":"participants","basis":"one per participant","confidence":"medium"},{"item":"Bedding and starter supplies","formula":"beneficiaries","basis":"one set per animal","confidence":"low","note":"Not stated in the catalogue. Confirm what travels with each animal."},{"item":"Water bowls","formula":"max(2, ceil(beneficiaries / 4))","basis":"animals on site need water","confidence":"low"},{"item":"Animals per handler","formula":"animals_per_handler","basis":"the partner sets its own ratio","confidence":"low","note":"Confirm the shelter''s required handler ratio. It is a welfare limit, not a preference."}],"resources":[{"key":"venue","label":"Venue","always":true,"fields":["name","address","contact_name","contact_phone","room","animal_policy","floor_protection","av_notes"],"note":"Live animals indoors need written venue permission and floor protection. Confirm both before anything else is booked."},{"key":"shelter_partner","label":"Shelter or rescue partner","always":true,"fields":["org_name","address","contact_name","contact_phone","contact_email","animal_count","handler_count","arrival_time","welfare_limits"]},{"key":"animal_transport","label":"Animal transport","condition":"beneficiary_travels","vehicle_rule":[{"when":"beneficiaries <= 6","vehicle":"Partner''s own vehicle","count_formula":"1"},{"when":"beneficiaries > 6","vehicle":"Animal transport van","count_formula":"ceil(beneficiaries / 8)"}],"fields":["vendor","vendor_phone","confirmation_number","vehicle_type","vehicle_count","pickup_time","cost"],"note":"Usually the partner''s own transport. Confirm who pays."},{"key":"home_delivery","label":"Home delivery to the shelter","condition":"homes_go_to_shelter","fields":["vendor","depart_time","arrive_time","destination","cost"]},{"key":"photography","label":"Photography","always":true,"fields":["photographer","contact","cost"]}],"run_of_show":{"anchor":"reveal","anchor_rule":"The animals arrive when the room hits its goal. If the partner sets a hard departure time, which animal welfare usually requires, the schedule is placed backward from it; otherwise it runs forward from arrival.","reveal_to_departure":30,"main_track":[{"id":"setup","label":"Setup","duration":75,"before_start":true,"details":["Floor protection laid","Build tables with one tool set each","Theater seating for the open and close","Audio and video check"]},{"id":"arrival","label":"Participants arrive and are seated","duration":10,"fixed":true,"details":["Teams pre-assigned and mixed across departments"]},{"id":"opening","label":"Opening remarks: client executive","duration":5,"fixed":true},{"id":"content","label":"Be Legendary content block","duration":15,"min":10,"details":["Connection Points woven in per the sponsor''s objectives"]},{"id":"build","label":"Build the animal homes","duration":25,"min":15,"details":["One home per team","Build instructions and client brief sheet issued","No mention of the animals"]},{"id":"reveal","label":"The Reveal: the group hits its goal and the animals arrive","duration":5,"fixed":true,"is_anchor":true},{"id":"present","label":"Teams meet the animals and present the homes","duration":15,"min":10,"details":["Handlers stay with the animals throughout","Roaming photography"]},{"id":"photo","label":"Group photograph","duration":5,"fixed":true},{"id":"reset","label":"Room reset for the debrief","duration":3,"fixed":true},{"id":"debrief","label":"Debrief, facilitated","duration":10,"min":5,"details":["What happened, so what, now what"]},{"id":"close","label":"Close: client executive","duration":4,"fixed":true},{"id":"loadout","label":"Homes loaded for delivery to the shelter","duration":45,"after_close":true}],"beneficiary_track":[{"id":"confirm","label":"Partner confirms animals, handlers and welfare limits","offset_from_reveal":-1440},{"id":"depart_origin","label":"Animals depart the shelter","offset_from_reveal":-60},{"id":"arrive_venue","label":"Animals arrive and go to the holding area, out of sight of the room","offset_from_reveal":-30},{"id":"holding","label":"Handlers settle the animals; water and quiet","offset_from_reveal":-30,"duration":25},{"id":"enter","label":"Animals enter with their handlers","offset_from_reveal":0},{"id":"return","label":"Animals returned to their handlers","offset_from_reveal":25},{"id":"depart_venue","label":"Animals depart the venue","offset_from_reveal":30}]},"tasks":[{"phase":"1. Lock","title":"Signed agreement / SOW returned","offset":-30,"role":"JC"},{"phase":"1. Lock","title":"Deposit invoice sent","offset":-30,"role":"JC"},{"phase":"1. Lock","title":"W-9, COI + vendor onboarding submitted","offset":-25,"role":"JC"},{"phase":"1. Lock","title":"Deposit received","offset":-21,"role":"JC"},{"phase":"1. Lock","title":"Travel booked for facilitation team","offset":-21,"role":"JC"},{"phase":"2. Design","title":"Sponsor alignment call held (objectives + success measures)","offset":-25,"role":"JC"},{"phase":"2. Design","title":"Connection Points agreed with the sponsor","offset":-21,"role":"JC","note":"Customized to the client''s objectives through Connection Points woven into the build."},{"phase":"2. Design","title":"Participant count and team count confirmed","offset":-21,"role":"JC"},{"phase":"2. Design","title":"Nonprofit partner matched and agreed","offset":-25,"role":"coordinator","note":"Benefits a vetted local nonprofit matched to the experience and the client''s market."},{"phase":"2. Design","title":"Attendee list + roles received","offset":-14,"role":"JC"},{"phase":"2. Design","title":"Content outline drafted","offset":-14,"role":"JC"},{"phase":"2. Design","title":"Content outline approved by sponsor","offset":-10,"role":"JC"},{"phase":"3. Produce","title":"Animal home kits ordered and ship date confirmed","offset":-21,"role":"logistics","note":"The catalogue states four to twelve weeks'' lead time is ideal. Offsets here sit at the short end; a larger room needs the long end."},{"phase":"3. Produce","title":"Run-of-show drafted","offset":-10,"role":"JC"},{"phase":"3. Produce","title":"AV + room requirements confirmed with venue","offset":-7,"role":"logistics"},{"phase":"3. Produce","title":"Run of show approved by sponsor","offset":-7,"role":"JC"},{"phase":"3. Produce","title":"Slides and media final","offset":-5,"role":"JC"},{"phase":"3. Produce","title":"Materials shipped; tracking number recorded","offset":-7,"role":"logistics"},{"phase":"3. Produce","title":"Materials arrival confirmed at venue","offset":-2,"role":"logistics"},{"phase":"3. Produce","title":"Final logistics email to sponsor","offset":-3,"role":"JC"},{"phase":"4. Deliver","title":"Delivery day","offset":0,"role":"all"},{"phase":"5. Close","title":"Thank-you + recap email to sponsor","offset":2,"role":"JC"},{"phase":"5. Close","title":"Participant feedback survey sent","offset":2,"role":"JC"},{"phase":"5. Close","title":"Photographs delivered to client","offset":3,"role":"logistics"},{"phase":"5. Close","title":"Final invoice sent","offset":3,"role":"JC"},{"phase":"5. Close","title":"Contractor invoices received and reconciled","offset":7,"role":"JC"},{"phase":"5. Close","title":"Event P&L closed","offset":10,"role":"JC"},{"phase":"5. Close","title":"Debrief call with sponsor held","offset":14,"role":"JC"},{"phase":"5. Close","title":"Final payment received","offset":30,"role":"JC"},{"phase":"2. Design","title":"Coordination letter sent to the nonprofit partner","offset":-21,"role":"coordinator"},{"phase":"2. Design","title":"Beneficiary count confirmed with the partner","offset":-18,"role":"coordinator"},{"phase":"3. Produce","title":"Beneficiary transport booked, confirmation number recorded","offset":-14,"role":"logistics","condition":"beneficiary_travels"},{"phase":"3. Produce","title":"Holding area confirmed, out of sight of the main room","offset":-7,"role":"coordinator","note":"If the beneficiaries can be seen before the reveal, the moment the room turns on is lost."},{"phase":"3. Produce","title":"Partner reconfirmed: arrival time, escorts, headcount","offset":-1,"role":"coordinator"},{"phase":"5. Close","title":"Thank-you to the nonprofit partner","offset":2,"role":"coordinator"},{"phase":"2. Design","title":"Animal count, species and sizes confirmed","offset":-18,"role":"coordinator","note":"Species and size change the home design. Confirm before kits are ordered."},{"phase":"2. Design","title":"Shelter welfare limits agreed: time on site, noise, handling","offset":-18,"role":"coordinator","note":"These are welfare limits, not preferences. They set the hard departure time."},{"phase":"3. Produce","title":"Written venue permission for live animals indoors","offset":-21,"role":"logistics","note":"Get this before anything else is booked. A venue refusal this late has no workaround."},{"phase":"3. Produce","title":"Floor protection confirmed and sourced","offset":-14,"role":"logistics","condition":"not floor_protection"},{"phase":"3. Produce","title":"Water bowls and bedding staged in the holding area","offset":-1,"role":"logistics"},{"phase":"4. Deliver","title":"Homes delivered to the shelter","offset":0,"role":"logistics","condition":"homes_go_to_shelter"},{"phase":"5. Close","title":"Adoption follow-up: did the animals find homes?","offset":30,"role":"coordinator","note":"The story the client will retell. Nobody finds out unless someone asks."}],"cost_lines":[{"key":"materials","label":"Materials and donated goods","visibility":"contractor"},{"key":"animal_transport","label":"Animal transport","visibility":"contractor"},{"key":"floor_protection","label":"Floor protection","visibility":"contractor"},{"key":"home_delivery","label":"Home delivery to the shelter","visibility":"contractor"},{"key":"print","label":"Printed materials","visibility":"contractor"},{"key":"freight","label":"Freight and shipping","visibility":"contractor"},{"key":"venue_av","label":"Venue and AV charges","visibility":"contractor"},{"key":"facilitation","label":"Facilitation crew","visibility":"contractor"},{"key":"photography","label":"Photography","visibility":"contractor"},{"key":"travel","label":"Facilitation team travel","visibility":"contractor"},{"key":"contractor_fees","label":"Contractor fees","visibility":"contractor"},{"key":"client_fee","label":"Client fee","